// Keep source identity and episode selection together throughout the workflow.
const activeSource = (config=state.config) => {const snapshot=config?.source;return snapshot?.kind==='green'&&MARKETS.some(m=>m.id===snapshot.market)&&snapshot.title&&Array.isArray(snapshot.availableEpisodes)?snapshot:resolveSource(config)||resolveSource({});};
const sourceLabel = config => {const src=activeSource(config);return src.kind==='green'?(MARKETS.find(m=>m.id===src.market)?.label+' · 合集 '+src.collectionId):'示例片源';};
function rangeError(src,start,end) {
 if(!src)return '请先选择一个合集';
 if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>src.totalEpisodes||start>end)return '请选择 1–'+src.totalEpisodes+' 集内的有效起止范围';
 const available=new Set(src.availableEpisodes),missing=Array.from({length:end-start+1},(_,i)=>start+i).filter(id=>!available.has(id));
 return missing.length?'第 '+missing.slice(0,8).join('、')+(missing.length>8?' 等':'')+' 集片源暂不可用，请调整范围':'';
}
function initialRange(src) {const ids=[...src.availableEpisodes].sort((a,b)=>a-b),start=ids[0]||1;let end=start;while(ids.includes(end+1)&&end<start+29)end++;return {start,end};}
function sourceRangeSummary(c=state.config) {const src=activeSource(c),error=rangeError(src,c.start,c.end);return error||'共 '+(c.end-c.start+1)+' 集 · 约 '+(c.end-c.start+1)*3+' 分钟';}
function syncSourceRange() {
 const el=$('#sourceRangeSummary');if(!el)return;const c=state.config,src=activeSource(),error=rangeError(src,c.start,c.end);
 el.textContent=sourceRangeSummary();el.classList.toggle('error-text',!!error);
 const track=$('#sourceRangeTrack');track.style.left=error?'0':(c.start-1)/src.totalEpisodes*100+'%';track.style.width=error?'0':(c.end-c.start+1)/src.totalEpisodes*100+'%';
 $$('[data-action="quick-range"]').forEach(b=>b.classList.toggle('active',c.start===1&&c.end===+b.dataset.end));
}
